def binary_search(sorted_list, target):
    """Return the index of target in sorted_list using binary search, or -1 if absent."""
    low, high = 0, len(sorted_list) - 1
    # Continue searching while the range is valid
    while low <= high:
        mid = (low + high) // 2
        if sorted_list[mid] == target:
            return mid
        if sorted_list[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

